const CARDS = [
  /* ───────────── RHETORISCHE STILMITTEL ───────────── */
  { id:'s01', deck:'stil', term:'Alliteration', def:'Mehrere aufeinanderfolgende Wörter beginnen mit demselben Anlaut.', ex:'„Milch macht müde Männer munter.“', fx:'Einprägsam, klangvoll; bindet Wörter zu einer Einheit. Werbung liebt sie.' },
  { id:'s02', deck:'stil', term:'Anapher', def:'Wiederholung eines Wortes oder einer Wortgruppe am Anfang aufeinanderfolgender Sätze, Verse oder Satzteile.', ex:'„Ich will das Land. Ich will die Freiheit. Ich will den Frieden.“', fx:'Eindringlichkeit, Rhythmus, Struktur. Gegenstück: Epipher (am Ende).' },
  { id:'s03', deck:'stil', term:'Epipher', def:'Wiederholung eines Wortes oder einer Wortgruppe am Ende aufeinanderfolgender Sätze oder Verse.', ex:'„Er sah das Meer, er liebte das Meer, er fürchtete das Meer.“', fx:'Betont das wiederholte Wort als Fixpunkt; wirkt wie ein Nachhall.' },
  { id:'s04', deck:'stil', term:'Antithese', def:'Gegenüberstellung entgegengesetzter Begriffe oder Gedanken.', ex:'„Der Wahn ist kurz, die Reu ist lang.“ (Schiller)', fx:'Verschärft den Kontrast, macht eine Spannung sichtbar. Nicht mit Oxymoron verwechseln (das ist EIN widersprüchlicher Ausdruck).' },
  { id:'s05', deck:'stil', term:'Chiasmus', def:'Überkreuzstellung: Satzglieder werden spiegelbildlich angeordnet (A B – B A).', ex:'„Die Kunst ist lang, und kurz ist unser Leben.“ (Goethe, Faust)', fx:'Betont einen Gegensatz durch die Spiegelung; wirkt geschlossen und kunstvoll. Merkhilfe: griechisches Chi = X.' },
  { id:'s06', deck:'stil', term:'Parallelismus', def:'Gleicher Satzbau in aufeinanderfolgenden Sätzen oder Satzteilen (A B – A B).', ex:'„Das Wasser rauscht, der Wind weht, die Sonne brennt.“', fx:'Ordnung, Rhythmus, Gleichgewicht; hebt Vergleichbares hervor. Gegenteil: Chiasmus.' },
  { id:'s07', deck:'stil', term:'Ellipse', def:'Auslassung eines Satzteils, der sich aus dem Zusammenhang ergänzen lässt.', ex:'„Ende gut, alles gut.“ – „Je später der Abend, desto schöner die Gäste.“', fx:'Knapp, schnell, umgangssprachlich; kann Hektik oder Sprachlosigkeit ausdrücken.' },
  { id:'s08', deck:'stil', term:'Hyperbel', def:'Starke Übertreibung.', ex:'„Ich habe dir das schon tausendmal gesagt.“', fx:'Verstärkung, Dramatisierung, oft komisch. Gegenteil: Litotes/Understatement.' },
  { id:'s09', deck:'stil', term:'Litotes', def:'Bejahung durch Verneinung des Gegenteils; Untertreibung.', ex:'„Das ist nicht schlecht.“ (= sehr gut) – „nicht wenig Geld“', fx:'Zurückhaltende Betonung, Ironie, Bescheidenheit.' },
  { id:'s10', deck:'stil', term:'Euphemismus', def:'Beschönigende Umschreibung eines unangenehmen Sachverhalts.', ex:'„Er ist von uns gegangen.“ (gestorben) – „Kollateralschaden“', fx:'Mildert, verschleiert, manipuliert. In Sachtexten oft ein Signal für Interessen des Autors.' },
  { id:'s11', deck:'stil', term:'Metapher', def:'Bildlicher Ausdruck: Ein Wort wird aus seinem eigentlichen Bereich in einen anderen übertragen – ohne Vergleichswort.', ex:'„Das Leben ist eine Reise.“ – „ein Meer von Tränen“', fx:'Veranschaulicht, verdichtet, erzeugt neue Bedeutung. Mit „wie“ wäre es ein Vergleich.' },
  { id:'s12', deck:'stil', term:'Vergleich', def:'Zwei Bereiche werden durch ein Vergleichswort („wie“, „als“) verbunden.', ex:'„Er kämpfte wie ein Löwe.“', fx:'Veranschaulichung; bleibt anders als die Metapher explizit.' },
  { id:'s13', deck:'stil', term:'Personifikation', def:'Vermenschlichung: Dingen, Tieren oder Abstrakta werden menschliche Eigenschaften oder Handlungen zugeschrieben.', ex:'„Die Sonne lacht.“ – „Der Wind flüstert.“', fx:'Belebt, macht Abstraktes greifbar, erzeugt Stimmung.' },
  { id:'s14', deck:'stil', term:'Metonymie', def:'Ersetzung eines Begriffs durch einen anderen, der in einer realen Beziehung zu ihm steht (Autor–Werk, Ort–Institution, Gefäß–Inhalt).', ex:'„Ich lese Goethe.“ – „Das Weiße Haus schweigt.“ – „ein Glas trinken“', fx:'Verkürzung, Konkretisierung. Anders als die Metapher gibt es einen sachlichen Zusammenhang, kein Bild.' },
  { id:'s15', deck:'stil', term:'Synekdoche', def:'Sonderform der Metonymie: Ein Teil steht für das Ganze (oder umgekehrt).', ex:'„Wir brauchen mehr Köpfe im Team.“ – „unter meinem Dach“', fx:'Pars pro toto: Verdichtung, Anschaulichkeit.' },
  { id:'s16', deck:'stil', term:'Oxymoron', def:'Verbindung zweier sich widersprechender Begriffe zu EINEM Ausdruck.', ex:'„beredtes Schweigen“ – „bittersüß“ – „alter Knabe“', fx:'Irritation, Verdichtung eines Widerspruchs. Bei Sätzen spricht man vom Paradoxon.' },
  { id:'s17', deck:'stil', term:'Paradoxon', def:'Scheinbar widersinnige Aussage, die bei genauerem Hinsehen eine tiefere Wahrheit enthält.', ex:'„Weniger ist mehr.“ – „Ich weiß, dass ich nichts weiß.“', fx:'Regt zum Nachdenken an, überrascht.' },
  { id:'s18', deck:'stil', term:'Rhetorische Frage', def:'Frage, auf die keine Antwort erwartet wird, weil sie offensichtlich ist.', ex:'„Wer will das schon?“ – „Ist das etwa gerecht?“', fx:'Bezieht den Leser ein, unterstellt Zustimmung, wirkt appellativ.' },
  { id:'s19', deck:'stil', term:'Klimax', def:'Steigerung: Reihung von Begriffen mit zunehmender Intensität.', ex:'„Er bat, er flehte, er schrie.“ – „Ich kam, sah und siegte.“', fx:'Spannungsaufbau, Dramatisierung. Gegenteil: Antiklimax.' },
  { id:'s20', deck:'stil', term:'Antiklimax', def:'Abstufung: Reihung mit abnehmender Intensität.', ex:'„Er verlor sein Haus, seinen Wagen, seinen Hut.“', fx:'Ernüchterung, oft komischer Effekt.' },
  { id:'s21', deck:'stil', term:'Inversion', def:'Umstellung der üblichen Wortfolge im Satz.', ex:'„Dunkel war die Nacht.“ – „Groß war seine Freude.“', fx:'Betonung des vorangestellten Wortes, feierlicher oder altertümlicher Klang.' },
  { id:'s22', deck:'stil', term:'Ironie', def:'Man sagt das Gegenteil dessen, was man meint – erkennbar am Kontext.', ex:'„Na, das hast du ja wieder toll hinbekommen!“ (nach einem Missgeschick)', fx:'Kritik, Spott, Distanz. Schärfere Form: Sarkasmus.' },
  { id:'s23', deck:'stil', term:'Symbol', def:'Konkretes Zeichen, das für etwas Abstraktes steht; die Bedeutung ist kulturell vereinbart oder im Text aufgebaut.', ex:'Taube = Frieden; rote Rose = Liebe; blaue Blume = romantische Sehnsucht', fx:'Verdichtet Bedeutung; in der Interpretation immer die Symbolik befragen.' },
  { id:'s24', deck:'stil', term:'Allegorie', def:'Durchgeführtes, ausgedeutetes Bild – oft ein personifizierter abstrakter Begriff mit festen Attributen.', ex:'Justitia mit Waage und Augenbinde; der Sensenmann für den Tod', fx:'Veranschaulicht Abstraktes in einer geschlossenen Bildwelt. Symbol = ein Zeichen, Allegorie = ein ganzes Bild.' },
  { id:'s25', deck:'stil', term:'Anakoluth', def:'Satzbruch: Ein Satz wird nicht so zu Ende geführt, wie er begonnen wurde.', ex:'„Ich wollte eigentlich – ach, vergiss es.“', fx:'Wirkt spontan, emotional, gesprochen; zeigt Verwirrung oder Abbruch.' },
  { id:'s26', deck:'stil', term:'Apostrophe', def:'Feierliche Anrede an eine abwesende Person, ein Ding oder einen abstrakten Begriff.', ex:'„O Freiheit, wo bist du?“ – „Du, mein geliebtes Regensburg!“', fx:'Pathos, Emotionalisierung, Nähe zum Angesprochenen.' },
  { id:'s27', deck:'stil', term:'Asyndeton', def:'Aufzählung OHNE verbindende Konjunktion.', ex:'„Wasser, Feuer, Erde, Luft.“', fx:'Beschleunigt, wirkt abgehackt und dicht. Gegenteil: Polysyndeton.' },
  { id:'s28', deck:'stil', term:'Polysyndeton', def:'Aufzählung MIT mehrfach wiederholter Konjunktion.', ex:'„Und es wallet und siedet und brauset und zischt.“ (Schiller)', fx:'Verlangsamt, wirkt gewichtig, betont jedes einzelne Glied.' },
  { id:'s29', deck:'stil', term:'Correctio', def:'Selbstverbesserung: Der Sprecher korrigiert einen Ausdruck sofort durch einen treffenderen.', ex:'„Er war groß, nein, riesig.“', fx:'Steigerung, wirkt spontan und glaubwürdig.' },
  { id:'s30', deck:'stil', term:'Neologismus', def:'Wortneuschöpfung.', ex:'„Knabenmorgenblütenträume“ (Goethe) – „Entschleunigung“', fx:'Originalität, Verdichtung; zeigt Grenzen der vorhandenen Sprache.' },
  { id:'s31', deck:'stil', term:'Archaismus', def:'Veraltetes Wort oder veraltete Wendung.', ex:'„Oheim“ (Onkel) – „Minne“ (Liebe) – „gülden“', fx:'Feierlich, altertümlich, ironisch-distanzierend.' },
  { id:'s32', deck:'stil', term:'Onomatopoesie (Lautmalerei)', def:'Wörter ahmen Geräusche klanglich nach.', ex:'„Es knistert und knackt im Kamin.“ – „Kuckuck“', fx:'Sinnlich, anschaulich; der Klang trägt die Bedeutung.' },
  { id:'s33', deck:'stil', term:'Pleonasmus', def:'Verbindung von Wörtern, bei der eines das andere bedeutungsmäßig bereits enthält.', ex:'„weißer Schimmel“ – „alter Greis“ – „runde Kugel“', fx:'Verstärkung, oft aber unfreiwillig komisch. Tautologie = gleiche Wortart („nie und nimmer“).' },
  { id:'s34', deck:'stil', term:'Tautologie', def:'Wiederholung desselben Gedankens durch zwei bedeutungsgleiche Wörter derselben Wortart.', ex:'„voll und ganz“ – „nie und nimmer“ – „Art und Weise“', fx:'Bekräftigung, Formelhaftigkeit.' },
  { id:'s35', deck:'stil', term:'Parenthese', def:'Einschub in einen Satz, meist durch Gedankenstriche oder Klammern abgetrennt.', ex:'„Der Mann – ich kannte ihn kaum – grüßte freundlich.“', fx:'Nebenbemerkung, Kommentar, Erklärung; kann den Fluss bewusst unterbrechen.' },
  { id:'s36', deck:'stil', term:'Zeugma', def:'Ein Verb bezieht sich auf zwei Objekte, die eigentlich nicht zusammenpassen.', ex:'„Er hob den Blick und ein Bier.“ – „Sie öffnete die Tür und ihr Herz.“', fx:'Komik, Überraschung; deckt Doppeldeutigkeit auf.' },
  { id:'s37', deck:'stil', term:'Akkumulation', def:'Häufung von Einzelbegriffen zu einem (oft ungenannten) Oberbegriff.', ex:'„Sonne, Mond und Sterne“ (= Himmel) – „Gabel, Messer, Löffel“ (= Besteck)', fx:'Fülle, Anschaulichkeit, Intensivierung.' },
  { id:'s38', deck:'stil', term:'Synästhesie', def:'Vermischung verschiedener Sinneseindrücke in einem Ausdruck.', ex:'„warme Farben“ – „schreiendes Rot“ – „der Töne Licht“ (Brentano)', fx:'Typisch für die Romantik: Verschmelzung, Entgrenzung der Wahrnehmung.' },
  { id:'s39', deck:'stil', term:'Hypotaxe', def:'Satzbau mit vielen untergeordneten Nebensätzen (Verschachtelung).', ex:'„Als er, der lange gezögert hatte, endlich kam, war es, obwohl niemand es erwartet hatte, zu spät.“', fx:'Komplex, differenziert, logisch; typisch für wissenschaftliche Texte und Kleist.' },
  { id:'s40', deck:'stil', term:'Parataxe', def:'Reihung gleichrangiger Hauptsätze.', ex:'„Er kam. Er sah. Er ging.“', fx:'Schlicht, schnell, sachlich; kann Atemlosigkeit oder Nüchternheit zeigen.' },
  { id:'s41', deck:'stil', term:'Repetitio (Wiederholung)', def:'Unmittelbare Wiederholung eines Wortes oder einer Wortgruppe.', ex:'„Nie, nie, nie werde ich das vergessen.“', fx:'Nachdruck, Emotion, Beschwörung.' },
  { id:'s42', deck:'stil', term:'Exclamatio (Ausruf)', def:'Ausruf, meist mit Ausrufezeichen.', ex:'„Was für ein Tag!“ – „Oh nein!“', fx:'Emotionalisierung, Unmittelbarkeit.' },
  { id:'s43', deck:'stil', term:'Sentenz', def:'Knapp formulierter, allgemeingültiger Sinnspruch.', ex:'„Was du heute kannst besorgen, das verschiebe nicht auf morgen.“', fx:'Wirkt wie ein Lehrsatz; verleiht Autorität.' },
  { id:'s44', deck:'stil', term:'Periphrase', def:'Umschreibung eines Begriffs durch charakteristische Merkmale.', ex:'„der Allmächtige“ (Gott) – „die Stadt der Liebe“ (Paris)', fx:'Vermeidet Wiederholung, wirkt gehoben; kann auch beschönigen (dann: Euphemismus).' },
  { id:'s45', deck:'stil', term:'Trikolon (Dreierfigur)', def:'Dreigliedrige Aufzählung.', ex:'„Freiheit, Gleichheit, Brüderlichkeit.“ – „Veni, vidi, vici.“', fx:'Wirkt vollständig und einprägsam; die Drei ist die „magische“ Zahl der Rhetorik.' },
  { id:'s46', deck:'stil', term:'Wortspiel', def:'Spiel mit Mehrdeutigkeit oder Klangähnlichkeit von Wörtern.', ex:'„Lieber arm dran als Arm ab.“', fx:'Witz, Überraschung; zeigt sprachliche Virtuosität.' },
  { id:'s47', deck:'stil', term:'Anspielung (Allusion)', def:'Indirekter Verweis auf ein bekanntes Ereignis, Werk oder eine Person.', ex:'„Das war sein Waterloo.“ – „Sein oder Nichtsein …“', fx:'Setzt Wissen voraus, schafft Verbindung zwischen Autor und Leser.' },
  { id:'s48', deck:'stil', term:'Sarkasmus', def:'Beißender, verletzender Spott – oft als übersteigerte Ironie.', ex:'„Danke für deine Hilfe – ohne dich wäre es nur halb so schiefgegangen.“', fx:'Angriff, Abwertung. Ironie ist die milde, Sarkasmus die scharfe Form.' },
  { id:'s49', deck:'stil', term:'Vergleich vs. Metapher (Abgrenzung)', def:'Vergleich: mit Vergleichswort („wie“, „als“). Metapher: ohne – das Bild ersetzt den Begriff direkt.', ex:'„Er ist stark wie ein Bär.“ (Vergleich) – „Er ist ein Bär.“ (Metapher)', fx:'Klassische Prüfungsfalle. Immer nach dem Vergleichswort suchen.' },

  /* ───────────── LYRIK ───────────── */
  { id:'l01', deck:'lyrik', term:'Jambus', def:'Versfuß: unbetont – betont (x X).', ex:'„Der MOND ist AUFgeGANgen“ (Claudius)', fx:'Häufigstes deutsches Versmaß. Wirkt fließend, natürlich, „aufsteigend“.' },
  { id:'l02', deck:'lyrik', term:'Trochäus', def:'Versfuß: betont – unbetont (X x).', ex:'„SAH ein KNAB ein RÖSlein STEHN“ (Goethe)', fx:'Wirkt fallend, liedhaft, manchmal hämmernd.' },
  { id:'l03', deck:'lyrik', term:'Daktylus', def:'Versfuß: betont – unbetont – unbetont (X x x).', ex:'„WIEder ein SONNtag, ein TAG ohne SORgen“', fx:'Wirkt tänzerisch, schwingend, bewegt. Merkhilfe: Daktylus = Finger (ein langes, zwei kurze Glieder).' },
  { id:'l04', deck:'lyrik', term:'Anapäst', def:'Versfuß: unbetont – unbetont – betont (x x X).', ex:'„In der NACHT, wenn der WIND durch die BÄUme fährt“', fx:'Wirkt vorwärtsdrängend, treibend. Umkehrung des Daktylus.' },
  { id:'l05', deck:'lyrik', term:'Kadenz', def:'Art des Versschlusses: männlich (stumpf) = endet betont; weiblich (klingend) = endet unbetont.', ex:'„… die Nacht“ (männlich) – „… die Wonne“ (weiblich)', fx:'Männliche Kadenz wirkt abgeschlossen und hart, weibliche weich und offen.' },
  { id:'l06', deck:'lyrik', term:'Paarreim', def:'Reimschema aabb: Zwei aufeinanderfolgende Verse reimen sich.', ex:'aabb', fx:'Einfach, volksliedhaft, einprägsam.' },
  { id:'l07', deck:'lyrik', term:'Kreuzreim', def:'Reimschema abab: Die Verse reimen sich über Kreuz.', ex:'abab', fx:'Verschränkt die Verse, wirkt ausgewogen und fließend.' },
  { id:'l08', deck:'lyrik', term:'Umarmender Reim', def:'Reimschema abba: Das äußere Reimpaar umschließt das innere.', ex:'abba', fx:'Wirkt geschlossen, ruhend; typisch für Sonett-Quartette.' },
  { id:'l09', deck:'lyrik', term:'Schweifreim', def:'Reimschema aabccb: Zwei Paarreime, deren dritte Verse sich reimen.', ex:'aabccb', fx:'Sechszeilige Strophe mit verbindendem „Schweif“.' },
  { id:'l10', deck:'lyrik', term:'Enjambement (Zeilensprung)', def:'Der Satz läuft über das Versende hinaus in den nächsten Vers.', ex:'„Ich weiß nicht, was soll es bedeuten, / dass ich so traurig bin“', fx:'Löst die Versgrenze auf, erzeugt Fluss oder Spannung; betont oft das Wort am Versende.' },
  { id:'l11', deck:'lyrik', term:'Zäsur', def:'Deutlicher Einschnitt (Sprechpause) innerhalb eines Verses.', ex:'„Du siehst, wohin du siehst, | nur Eitelkeit auf Erden“ (Gryphius)', fx:'Gliedert den Vers, bremst, betont. Pflicht im Alexandriner.' },
  { id:'l12', deck:'lyrik', term:'Sonett', def:'Gedichtform aus 14 Versen: zwei Quartette (4 Verse) und zwei Terzette (3 Verse), meist fünfhebiger Jambus, Reim oft abba abba cdc dcd.', ex:'Gryphius „Es ist alles eitel“; Rilke „Archaischer Torso Apollos“', fx:'Typischer Aufbau: Quartette stellen dar, Terzette wenden/deuten. Barock, Romantik, Expressionismus.' },
  { id:'l13', deck:'lyrik', term:'Ode', def:'Feierliches, erhabenes Gedicht in strenger Strophenform, reimlos, oft an eine Person oder Idee gerichtet.', ex:'Klopstock, Hölderlin; Schillers „An die Freude“ (odenhaft)', fx:'Pathos, hoher Ton.' },
  { id:'l14', deck:'lyrik', term:'Hymne', def:'Feierlicher Lob- oder Preisgesang in freien Rhythmen, ohne feste Strophenform.', ex:'Goethe „Prometheus“, „Ganymed“', fx:'Ekstatisch, überschwänglich; Sturm und Drang.' },
  { id:'l15', deck:'lyrik', term:'Elegie', def:'Klagegedicht in wehmütigem, trauerndem Ton; klassisch im Distichon.', ex:'Goethe „Römische Elegien“; Rilke „Duineser Elegien“', fx:'Trauer, Sehnsucht, Verlust.' },
  { id:'l16', deck:'lyrik', term:'Ballade', def:'Erzählendes Gedicht, das lyrische, epische und dramatische Elemente vereint; oft mit dramatischem Höhepunkt.', ex:'Goethe „Erlkönig“; Schiller „Der Taucher“; Fontane „John Maynard“', fx:'Spannung, Dialoge, Wendepunkt. Goethe: „Ur-Ei“ der Dichtung.' },
  { id:'l17', deck:'lyrik', term:'Lyrisches Ich', def:'Die sprechende Instanz im Gedicht – nicht gleichzusetzen mit dem Autor.', ex:'„Ich weiß nicht, was soll es bedeuten“ – das Ich ist Heines Sprecherfigur, nicht Heine selbst.', fx:'Prüfungsfalle: nie „der Dichter fühlt“ schreiben, sondern „das lyrische Ich“.' },
  { id:'l18', deck:'lyrik', term:'Freie Rhythmen', def:'Verse ohne festes Metrum, ohne Reim und ohne feste Strophenform – aber rhythmisch gestaltet.', ex:'Goethe „Prometheus“; Hölderlin; Expressionismus', fx:'Wirkt spontan, ungebunden, pathetisch. Nicht mit Prosa verwechseln: Versgrenzen bleiben.' },
  { id:'l19', deck:'lyrik', term:'Blankvers', def:'Reimloser fünfhebiger Jambus.', ex:'Lessing „Nathan der Weise“; Goethe „Iphigenie“; Schiller „Don Karlos“', fx:'Der klassische deutsche Dramenvers – natürlich und gehoben zugleich.' },
  { id:'l20', deck:'lyrik', term:'Alexandriner', def:'Sechshebiger Jambus mit Zäsur nach der dritten Hebung, meist paargereimt.', ex:'„Du siehst, wohin du siehst, | nur Eitelkeit auf Erden“ (Gryphius)', fx:'Der Vers des Barock; die Zäsur passt zur antithetischen Weltsicht.' },
  { id:'l21', deck:'lyrik', term:'Knittelvers', def:'Vierhebiger Vers mit Paarreim und freier Füllung der Senkungen.', ex:'„Habe nun, ach! Philosophie, / Juristerei und Medizin …“ (Goethe, Faust)', fx:'Volkstümlich, derb, altdeutsch (Hans Sachs); Goethe nutzt ihn bewusst im Faust.' },
  { id:'l22', deck:'lyrik', term:'Hexameter', def:'Sechshebiger daktylischer Vers (Daktylen können durch Trochäen ersetzt werden).', ex:'Homer; Goethe „Hermann und Dorothea“; Klopstock „Messias“', fx:'Der antike Epenvers; wirkt breit, erzählend, erhaben.' },
  { id:'l23', deck:'lyrik', term:'Distichon', def:'Zweizeiler aus Hexameter und Pentameter.', ex:'„Im Hexameter steigt des Springquells flüssige Säule, / im Pentameter drauf fällt sie melodisch herab.“ (Schiller)', fx:'Form der Elegie und des Epigramms in der Klassik.' },
  { id:'l24', deck:'lyrik', term:'Epigramm', def:'Kurzes, pointiertes Sinngedicht, oft zweizeilig mit überraschender Schlusswendung.', ex:'Lessing, Schiller/Goethe „Xenien“', fx:'Witz, Schärfe, Zuspitzung.' },
  { id:'l25', deck:'lyrik', term:'Reiner / unreiner Reim', def:'Rein: Vokale und Folgekonsonanten stimmen exakt überein. Unrein: nur ähnlich.', ex:'rein: „Herz – Schmerz“, „Liebe – Triebe“; unrein: „schön – gehn“, „Freund – meint“', fx:'Unreine Reime können Absicht sein (Brüchigkeit, Ironie) oder dialektal bedingt.' },
  { id:'l26', deck:'lyrik', term:'Binnenreim', def:'Reim innerhalb eines Verses (nicht am Versende).', ex:'„Wer nie sein Brot mit Tränen aß“ – „Es schwirrt und klirrt im Geäst“', fx:'Klangliche Verdichtung im Versinneren.' },
  { id:'l27', deck:'lyrik', term:'Hebung und Senkung', def:'Hebung = betonte Silbe, Senkung = unbetonte Silbe. Die Abfolge ergibt das Metrum.', ex:'Jambus: Senkung–Hebung; Trochäus: Hebung–Senkung', fx:'„Fünfhebig“ = fünf betonte Silben pro Vers.' },
  { id:'l28', deck:'lyrik', term:'Volksliedstrophe', def:'Vierzeilige Strophe, meist Kreuzreim, drei- oder vierhebig, abwechselnde Kadenzen.', ex:'Eichendorff „Mondnacht“; Heine „Loreley“', fx:'Einfachheit, Sangbarkeit; Romantiker greifen bewusst darauf zurück.' },
  { id:'l29', deck:'lyrik', term:'Chiffre', def:'Bild, dessen Bedeutung nicht mehr allgemein entschlüsselbar ist – nur aus dem Werk des Autors heraus.', ex:'Celans „schwarze Milch“ („Todesfuge“); Trakls Farben', fx:'Moderne Lyrik: Symbol wird zur privaten, hermetischen Chiffre.' },

  /* ───────────── EPIK ───────────── */
  { id:'e01', deck:'epik', term:'Erzähler ≠ Autor', def:'Der Erzähler ist eine vom Autor erfundene Vermittlungsinstanz im Text – nie mit dem realen Verfasser gleichzusetzen.', ex:'Auch wenn Thomas Mann Zauberberg-Erzähler klingt: „der Erzähler“, nicht „Mann“.', fx:'Grundregel jeder Epik-Analyse.' },
  { id:'e02', deck:'epik', term:'Ich-Erzähler / Er-Sie-Erzähler (Erzählform)', def:'Erzählform: Ich-Erzähler ist selbst Figur der Geschichte; Er/Sie-Erzähler steht außerhalb.', ex:'„Homo faber“ (Ich) vs. „Effi Briest“ (Er/Sie)', fx:'Ich-Erzähler = subjektiv, begrenzt, oft unzuverlässig.' },
  { id:'e03', deck:'epik', term:'Auktoriales Erzählverhalten', def:'Allwissender Erzähler: Überblick über alle Figuren, Kommentare, Wertungen, Vorausdeutungen, direkte Leseransprache.', ex:'Fontane, Th. Mann („Buddenbrooks“)', fx:'Distanz, Ordnung, Lenkung des Lesers. Lateinisch auctor = Urheber.' },
  { id:'e04', deck:'epik', term:'Personales Erzählverhalten', def:'Der Erzähler tritt zurück und erzählt aus der Perspektive einer Figur (Innensicht); Wissen ist auf sie beschränkt.', ex:'Kafka „Die Verwandlung“ (alles aus Gregors Sicht)', fx:'Nähe, Unmittelbarkeit, Identifikation; erlebte Rede und innerer Monolog sind typisch.' },
  { id:'e05', deck:'epik', term:'Neutrales Erzählverhalten', def:'Der Erzähler berichtet nur Beobachtbares wie eine Kamera – keine Innensicht, keine Wertung.', ex:'Kurzgeschichten der Nachkriegszeit, Hemingway', fx:'Sachlich, kühl; der Leser muss selbst deuten.' },
  { id:'e06', deck:'epik', term:'Innensicht / Außensicht', def:'Innensicht: Erzähler zeigt Gedanken und Gefühle einer Figur. Außensicht: nur Handlungen und Äußeres.', ex:'„Sie fühlte sich verloren“ (innen) vs. „Sie zog die Schultern hoch“ (außen)', fx:'Grad der Innensicht bestimmt die Nähe zur Figur.' },
  { id:'e07', deck:'epik', term:'Erzählzeit / erzählte Zeit', def:'Erzählzeit: Zeit, die das Lesen/Erzählen braucht. Erzählte Zeit: Zeit, die in der Geschichte vergeht.', ex:'Zwei Seiten (Erzählzeit) über zehn Jahre (erzählte Zeit)', fx:'Verhältnis ergibt Zeitraffung, Zeitdehnung oder Zeitdeckung.' },
  { id:'e08', deck:'epik', term:'Zeitraffung / Zeitdehnung / Zeitdeckung', def:'Raffung: erzählte Zeit > Erzählzeit. Dehnung: erzählte Zeit < Erzählzeit. Deckung: gleich (z. B. Dialog).', ex:'„Jahre vergingen.“ (Raffung) – ein Sekundenbruchteil auf drei Seiten (Dehnung)', fx:'Dehnung = Bedeutung; Raffung = Unwichtiges. Wo der Erzähler die Zeit dehnt, liegt der Kern.' },
  { id:'e09', deck:'epik', term:'Rückblende (Analepse) / Vorausdeutung (Prolepse)', def:'Rückblende: Einschub von Vergangenem. Vorausdeutung: Hinweis auf Späteres.', ex:'„Homo faber“ ist als Rückblick aufgebaut; auktoriale Erzähler deuten gern voraus.', fx:'Bricht die Chronologie; erzeugt Spannung oder Schicksalhaftigkeit.' },
  { id:'e10', deck:'epik', term:'Erlebte Rede', def:'Gedanken einer Figur in der 3. Person und im Präteritum, ohne Anführungszeichen – Erzähler und Figur verschmelzen.', ex:'„Was sollte er jetzt nur tun? Alles war verloren.“', fx:'Innensicht bei personalem Erzählen. Merkmal: 3. Person + Präteritum + Frage-/Ausrufesyntax.' },
  { id:'e11', deck:'epik', term:'Innerer Monolog', def:'Gedanken einer Figur direkt wiedergegeben: 1. Person, Präsens, ohne Erzählervermittlung.', ex:'„Was soll ich nur tun? Alles ist verloren.“ (Schnitzler „Leutnant Gustl“)', fx:'Höchste Nähe. Unterschied zur erlebten Rede: ich/Präsens statt er/Präteritum.' },
  { id:'e12', deck:'epik', term:'Bewusstseinsstrom (stream of consciousness)', def:'Ungeordnete, assoziative Wiedergabe von Gedanken, Wahrnehmungen und Erinnerungen – oft ohne Syntax und Interpunktion.', ex:'Joyce „Ulysses“; Döblin „Berlin Alexanderplatz“', fx:'Moderne: Abbildung des zerfallenden, fließenden Ich.' },
  { id:'e13', deck:'epik', term:'Direkte / indirekte Rede', def:'Direkt: wörtlich mit Anführungszeichen. Indirekt: im Konjunktiv wiedergegeben.', ex:'„Ich komme“, sagte er. – Er sagte, er komme.', fx:'Direkte Rede = Nähe, Lebendigkeit; indirekte Rede = Distanz.' },
  { id:'e14', deck:'epik', term:'Novelle', def:'Mittellange Erzählung um eine „unerhörte Begebenheit“ (Goethe), straff gebaut, mit Wendepunkt und oft einem Dingsymbol („Falke“).', ex:'Storm „Der Schimmelreiter“; Kleist „Das Erdbeben in Chili“; Th. Mann „Tod in Venedig“', fx:'„Schwester des Dramas“ (Storm): geschlossener Aufbau, Höhepunkt.' },
  { id:'e15', deck:'epik', term:'Kurzgeschichte', def:'Kurze Prosaform: unmittelbarer Anfang, offener Schluss, Alltagsfiguren, ein Ausschnitt, oft ein Wendepunkt; Alltagssprache.', ex:'Borchert „Das Brot“; Böll; Bichsel', fx:'Nach 1945 aus der amerikanischen short story übernommen (Kahlschlag).' },
  { id:'e16', deck:'epik', term:'Parabel', def:'Lehrhafte Erzählung mit zwei Ebenen: Bildebene (erzählt) und Sachebene (gemeint) – der Leser muss übertragen.', ex:'Kafka „Vor dem Gesetz“; Brecht „Geschichten vom Herrn Keuner“; Lessings Ringparabel', fx:'Analyse: Bildebene beschreiben → Sachebene erschließen → Übertragung begründen.' },
  { id:'e17', deck:'epik', term:'Fabel', def:'Kurze lehrhafte Erzählung, in der Tiere wie Menschen handeln; Lehre (Moral) am Ende.', ex:'Äsop; Lessing „Der Rabe und der Fuchs“', fx:'Aufklärung: Belehrung durch Verkleidung; Tiere = feste Typen.' },
  { id:'e18', deck:'epik', term:'Leitmotiv', def:'Wiederkehrendes Motiv (Gegenstand, Wendung, Bild), das den Text strukturiert und Bedeutung aufbaut.', ex:'Die „Gnadenfrist“ und das Rasieren in „Homo faber“; Hans Castorps Zigarre', fx:'Beim Lesen markieren: Wiederholung = Bedeutung.' },
  { id:'e19', deck:'epik', term:'Dingsymbol', def:'Konkreter Gegenstand, der in der Erzählung symbolische Bedeutung trägt (in der Novelle: „Falke“).', ex:'Der Schimmel in Storms „Schimmelreiter“; Effis Schaukel', fx:'Verdichtet das Thema in einem Ding.' },
  { id:'e20', deck:'epik', term:'Rahmen- und Binnenerzählung', def:'Eine äußere Erzählsituation (Rahmen) umschließt die eigentliche Geschichte (Binnenerzählung).', ex:'„Der Schimmelreiter“ (dreifacher Rahmen); „Die Judenbuche“', fx:'Beglaubigung, Distanz, Mehrdeutigkeit durch mehrere Erzählinstanzen.' },
  { id:'e21', deck:'epik', term:'Charakterisierung: direkt / indirekt', def:'Direkt: Erzähler oder Figur benennt Eigenschaften. Indirekt: Eigenschaften erschließen sich aus Handeln, Sprechen, Aussehen, Umgebung.', ex:'„Er war geizig.“ (direkt) – Er zählte jeden Cent nach. (indirekt)', fx:'In der Analyse immer angeben, WIE charakterisiert wird.' },
  { id:'e22', deck:'epik', term:'Unzuverlässiger Erzähler', def:'Erzähler, dessen Darstellung der Leser nicht trauen kann – aus Selbsttäuschung, Verdrängung oder Absicht.', ex:'Walter Faber („Homo faber“) beschönigt sein Verhalten; Oskar Matzerath', fx:'Deutungshinweis: Widersprüche zwischen Behauptung und erzähltem Verhalten suchen.' },
  { id:'e23', deck:'epik', term:'Figurenkonstellation', def:'Geflecht der Beziehungen zwischen den Figuren: Haupt-/Nebenfiguren, Gegenspieler, Parallelfiguren.', ex:'Effi – Innstetten – Crampas; Faust – Mephisto – Gretchen', fx:'Als Skizze mit Pfeilen anlegen; zeigt Konfliktlinien.' },
  { id:'e24', deck:'epik', term:'Fiktionalität', def:'Literarische Texte sind erfunden; sie beanspruchen keine Faktentreue, sondern entwerfen eine eigene Welt.', ex:'Ein Roman über Napoleon ist Fiktion, auch wenn Napoleon real war.', fx:'Lehrplan: Literatur als „Simulationsraum“ / „modellhafter Entwurf von Welt“.' },

  /* ───────────── DRAMA ───────────── */
  { id:'d01', deck:'drama', term:'Akt / Szene', def:'Akt (Aufzug): großer Abschnitt, oft durch Ortswechsel oder Vorhang getrennt. Szene (Auftritt): Unterabschnitt, endet bei Auf-/Abtritt einer Figur.', ex:'Klassisches Drama: 5 Akte; „Faust I“ ohne Akteinteilung, nur Szenen', fx:'Bei Zitaten: Akt in römischen, Szene in arabischen Zahlen (III,2).' },
  { id:'d02', deck:'drama', term:'Geschlossenes Drama', def:'Straffer, symmetrischer Aufbau (meist 5 Akte), Einheit von Ort, Zeit und Handlung, wenige Figuren hohen Standes, gehobene Sprache (Vers).', ex:'Goethe „Iphigenie“; Schiller „Maria Stuart“; Lessing „Emilia Galotti“', fx:'Aristotelische Tradition; Klassik. Gegenteil: offenes Drama.' },
  { id:'d03', deck:'drama', term:'Offenes Drama', def:'Lockere Reihung von Szenen (Stationen), viele Orte und Zeiten, Figuren aller Stände, Prosa und Umgangssprache, oft fragmentarisch.', ex:'Büchner „Woyzeck“; Goethe „Götz“; Sturm und Drang, Expressionismus', fx:'Wirklichkeit ist chaotisch – die Form zeigt es.' },
  { id:'d04', deck:'drama', term:'Freytags Pyramide', def:'Idealaufbau des geschlossenen Dramas: 1. Exposition, 2. steigende Handlung (erregendes Moment), 3. Höhepunkt/Peripetie, 4. fallende Handlung (retardierendes Moment), 5. Katastrophe/Lösung.', ex:'Gustav Freytag, „Die Technik des Dramas“ (1863)', fx:'Fünf Akte = fünf Stufen. Als Skizze zeichnen.' },
  { id:'d05', deck:'drama', term:'Exposition', def:'Einführung zu Beginn: Ort, Zeit, Figuren, Vorgeschichte, Ausgangskonflikt.', ex:'1. Akt „Emilia Galotti“: Der Prinz sieht Emilias Bild', fx:'Frage: Welche Informationen bekommt der Zuschauer wie (Dialog, Monolog, Bote)?' },
  { id:'d06', deck:'drama', term:'Peripetie', def:'Wendepunkt: Umschlag der Handlung ins Gegenteil, meist im 3. Akt.', ex:'„Maria Stuart“: das Treffen der Königinnen (III,4) besiegelt Marias Schicksal', fx:'Griechisch „Umschwung“. Ab hier geht es für den Helden bergab (Tragödie).' },
  { id:'d07', deck:'drama', term:'Retardierendes Moment', def:'Verzögerung vor der Katastrophe: Ein Ausweg scheint möglich, die Spannung wird noch einmal gesteigert.', ex:'4. Akt: Hoffnung auf Rettung, die dann scheitert', fx:'Lateinisch retardare = verzögern.' },
  { id:'d08', deck:'drama', term:'Katastrophe', def:'Schlussteil der Tragödie: Untergang des Helden, Lösung des Konflikts durch Tod oder Scheitern.', ex:'Emilia lässt sich von ihrem Vater erstechen', fx:'In der Komödie entsprechend: Lösung (Happy End).' },
  { id:'d09', deck:'drama', term:'Katharsis', def:'Nach Aristoteles: Reinigung des Zuschauers von Affekten durch das Erleben von Jammer/Mitleid (eleos) und Schauder/Furcht (phobos).', ex:'Aristoteles, „Poetik“; Lessing deutet es als Mitleid und Furcht', fx:'Ziel der aristotelischen Tragödie. Brecht lehnt genau das ab.' },
  { id:'d10', deck:'drama', term:'Ständeklausel', def:'Regel, dass in der Tragödie nur Figuren hohen Standes (Adel) auftreten, in der Komödie das niedere Volk.', ex:'Von Lessing mit dem bürgerlichen Trauerspiel durchbrochen', fx:'Begründung: Fallhöhe. Aufklärung: Bürger sind ebenso tragikfähig.' },
  { id:'d11', deck:'drama', term:'Fallhöhe', def:'Abstand zwischen der Ausgangsposition des Helden und seinem Untergang – je höher, desto tragischer.', ex:'Ein König, der alles verliert, hat eine größere Fallhöhe als ein Bettler', fx:'Argument hinter der Ständeklausel.' },
  { id:'d12', deck:'drama', term:'Bürgerliches Trauerspiel', def:'Tragödie mit bürgerlichen Hauptfiguren, Familien- und Standeskonflikte, Prosa oder Vers; Aufklärung und Sturm und Drang.', ex:'Lessing „Miss Sara Sampson“ (1755, das erste), „Emilia Galotti“; Schiller „Kabale und Liebe“', fx:'Bruch mit der Ständeklausel; das Bürgertum wird tragikfähig.' },
  { id:'d13', deck:'drama', term:'Episches Theater', def:'Brechts Gegenmodell zum aristotelischen Drama: Der Zuschauer soll nicht mitfühlen, sondern kritisch beobachten und die Welt als veränderbar erkennen.', ex:'Brecht „Mutter Courage“, „Leben des Galilei“, „Der gute Mensch von Sezuan“', fx:'Mittel: Verfremdung, Songs, Erzähler, Spruchbänder, offene Szenenfolge, Historisierung.' },
  { id:'d14', deck:'drama', term:'Verfremdungseffekt (V-Effekt)', def:'Brechts Technik, Vertrautes fremd erscheinen zu lassen, damit der Zuschauer die Illusion durchschaut und nachdenkt.', ex:'Schauspieler treten aus der Rolle, Songs unterbrechen, Projektionen kommentieren', fx:'Ziel: Distanz statt Einfühlung. „Das Selbstverständliche unverständlich machen.“' },
  { id:'d15', deck:'drama', term:'Aristotelisches vs. episches Theater', def:'Aristotelisch: Einfühlung, Illusion, Katharsis, geschlossene Form, Zuschauer wird „verwickelt“. Episch: Distanz, Verfremdung, Erkenntnis, offene Form, Zuschauer wird „gegenübergesetzt“.', ex:'Brechts Gegenüberstellung im „Kleinen Organon“', fx:'Beliebte Vergleichsaufgabe. Tabelle mit Gegensatzpaaren lernen.' },
  { id:'d16', deck:'drama', term:'Monolog', def:'Eine Figur spricht allein (Selbstgespräch), oft um Gedanken, Pläne oder Konflikte offenzulegen.', ex:'Fausts Eingangsmonolog „Habe nun, ach! …“', fx:'Direkter Zugang zur Innenwelt; Ersatz für den fehlenden Erzähler.' },
  { id:'d17', deck:'drama', term:'Beiseitesprechen (a parte)', def:'Eine Figur spricht zum Publikum, ohne dass die anderen Figuren es hören.', ex:'Mephisto kommentiert Fausts Verhalten', fx:'Komplizenschaft mit dem Zuschauer; Ironie.' },
  { id:'d18', deck:'drama', term:'Stichomythie', def:'Schneller Wechselrede-Dialog, bei dem sich die Figuren Vers für Vers abwechseln.', ex:'Streitgespräche bei Schiller und Goethe', fx:'Erregung, Konflikt, Tempo.' },
  { id:'d19', deck:'drama', term:'Haupttext / Nebentext', def:'Haupttext: die gesprochenen Repliken. Nebentext: Regieanweisungen, Personenverzeichnis, Titel, Szenenangaben.', ex:'„(ab)“, „(leise)“, „Ein enges gotisches Zimmer“', fx:'Im offenen Drama und bei Brecht ist der Nebentext oft ausführlich und bedeutungstragend.' },
  { id:'d20', deck:'drama', term:'Botenbericht', def:'Ein Bote berichtet von Ereignissen, die außerhalb der Bühne stattgefunden haben.', ex:'Der Bote meldet den Ausgang der Schlacht', fx:'Wahrt die Einheit des Ortes; vermeidet Gewalt auf der Bühne.' },
  { id:'d21', deck:'drama', term:'Mauerschau (Teichoskopie)', def:'Eine Figur beschreibt von einem erhöhten Punkt aus Vorgänge, die das Publikum nicht sehen kann – gleichzeitig zum Geschehen.', ex:'Eine Figur schildert vom Turm herab die herannahende Schlacht', fx:'Unterschied zum Botenbericht: gleichzeitig statt nachträglich.' },
  { id:'d22', deck:'drama', term:'Tragödie / Komödie / Tragikomödie', def:'Tragödie: Untergang des Helden. Komödie: Konflikt löst sich heiter. Tragikomödie: Mischung, das Tragische wird lächerlich und umgekehrt.', ex:'Dürrenmatt „Der Besuch der alten Dame“, „Die Physiker“ (Tragikomödien)', fx:'Dürrenmatt: „Uns kommt nur noch die Komödie bei.“' },
  { id:'d23', deck:'drama', term:'Drei Einheiten', def:'Einheit von Ort, Zeit (ein Tag) und Handlung (ein Strang) – aus Aristoteles abgeleitete Regel für das geschlossene Drama.', ex:'Gottsched fordert sie; Lessing lockert; Sturm und Drang bricht sie', fx:'Nur die Einheit der Handlung steht wirklich bei Aristoteles.' },
  { id:'d24', deck:'drama', term:'Deus ex machina', def:'Unerwartete, „von außen“ kommende Lösung eines Konflikts, die aus der Handlung nicht folgt.', ex:'Die drei Götter im „Guten Menschen von Sezuan“ (ironisch); antike Bühnenmaschine', fx:'Lateinisch „Gott aus der Maschine“; meist kritisch gemeint.' },
  { id:'d25', deck:'drama', term:'Dramatischer Konflikt', def:'Zentraler Gegensatz, der die Handlung antreibt: zwischen Figuren, zwischen Figur und Gesellschaft, oder innerhalb einer Figur.', ex:'Pflicht vs. Neigung (Klassik); Individuum vs. Gesellschaft (Woyzeck)', fx:'Erste Frage der Dramenanalyse: Wer will was gegen wen?' },

  /* ───────────── EPOCHEN ───────────── */
  { id:'p01', deck:'epochen', term:'Barock', def:'ca. 1600–1720 · Dreißigjähriger Krieg · Vanitas (Vergänglichkeit), Memento mori, Carpe diem · Antithetik Diesseits/Jenseits · strenge Formen (Sonett, Alexandriner)', ex:'Gryphius „Es ist alles eitel“, „Tränen des Vaterlandes“; Opitz; Grimmelshausen „Simplicissimus“', fx:'Erkennungszeichen: Alexandriner mit Zäsur, Antithesen, Vergänglichkeitsbilder.' },
  { id:'p02', deck:'epochen', term:'Aufklärung', def:'ca. 1720–1785 · Vernunft, Toleranz, Erziehung des Menschen · Kant: „Sapere aude!“ · Bürgertum emanzipiert sich · Literatur soll belehren und bessern', ex:'Lessing „Nathan der Weise“ (Ringparabel), „Emilia Galotti“; Fabeln; Gottsched', fx:'Lehrplan: Grundlage, auf der Klassik aufbaut. Lieblingsgattungen: Fabel, Parabel, bürgerliches Trauerspiel.' },
  { id:'p03', deck:'epochen', term:'Sturm und Drang', def:'ca. 1765–1785 · Jugendbewegung gegen Regelzwang und Autoritäten · Genie, Gefühl, Natur, Freiheit · Kraftsprache, offene Dramenform, Hymnen in freien Rhythmen', ex:'Goethe „Werther“, „Götz“, „Prometheus“; Schiller „Die Räuber“, „Kabale und Liebe“', fx:'Nicht Gegenteil, sondern Radikalisierung der Aufklärung: Der Einzelne gegen die Ordnung.' },
  { id:'p04', deck:'epochen', term:'Weimarer Klassik', def:'1786–1805 (Goethes Italienreise bis Schillers Tod) · Humanitätsideal, Harmonie von Vernunft und Gefühl, Bildungsidee · Formstrenge, Blankvers, Orientierung an der Antike · Maß, Ausgleich, „edle Einfalt, stille Größe“', ex:'Goethe „Iphigenie auf Tauris“, „Faust I“; Schiller „Maria Stuart“, „Wilhelm Tell“, „Das Lied von der Glocke“', fx:'Lehrplan D12 nennt ausdrücklich: Humanitäts- und Harmonieideal, Bildungsidee, Formstrenge.' },
  { id:'p05', deck:'epochen', term:'Romantik', def:'ca. 1795–1835 · Absolutsetzung des Subjekts (Gefühl, Fantasie, Traum) · Universalpoesie (F. Schlegel: alles verschmelzen) · Sehnsucht, Nacht, Ferne, blaue Blume, Wandern · Kritik an Vernunft und Nützlichkeit · Gefährdung: Wahnsinn, Doppelgänger, das Unheimliche', ex:'Novalis „Heinrich von Ofterdingen“; Eichendorff „Taugenichts“, „Mondnacht“; E.T.A. Hoffmann „Der Sandmann“; Brentano; Tieck', fx:'Lehrplan: „Absolutsetzung des Subjekts und daraus resultierende Gefährdung, Universalpoesie“. Schwarze Romantik = Hoffmann.' },
  { id:'p06', deck:'epochen', term:'Biedermeier', def:'1815–1848 (Wiener Kongress bis Märzrevolution) · Rückzug ins Private, Häuslichkeit, Resignation, Ordnung · Naturidylle, Melancholie', ex:'Mörike; Droste-Hülshoff „Die Judenbuche“; Stifter; Grillparzer', fx:'Gleichzeitig mit dem Vormärz – dieselbe Zeit, zwei Reaktionen auf die Restauration.' },
  { id:'p07', deck:'epochen', term:'Vormärz / Junges Deutschland', def:'1815–1848 · politisch engagierte Literatur vor der Märzrevolution · Kritik an Restauration, Zensur, Adel · Forderung nach Freiheit und Demokratie · realistische, oft satirische Sprache', ex:'Büchner „Woyzeck“, „Der Hessische Landbote“; Heine „Deutschland. Ein Wintermärchen“; Herwegh', fx:'Büchner: „Friede den Hütten! Krieg den Palästen!“' },
  { id:'p08', deck:'epochen', term:'Realismus', def:'ca. 1848–1890 · Poetisierung der Wirklichkeit: Alltag wird dargestellt, aber künstlerisch verklärt („poetischer/bürgerlicher Realismus“) · Idealismus-Kritik · Objektivität, Humor, Distanz · Auseinandersetzung mit Naturwissenschaft und Politik', ex:'Fontane „Effi Briest“, „Irrungen, Wirrungen“; Storm „Der Schimmelreiter“; Keller „Kleider machen Leute“; Raabe', fx:'Lehrplan: „Idealismus-Kritik, Poetisierung der Wirklichkeit“. Lieblingsgattungen: Novelle, Gesellschaftsroman.' },
  { id:'p09', deck:'epochen', term:'Naturalismus', def:'ca. 1880–1900 · radikale Abbildung sozialer Wirklichkeit: Elend, Arbeiterwelt, Alkohol, Krankheit · Milieu und Vererbung bestimmen den Menschen (Determinismus) · Sekundenstil, Dialekt · Formel: „Kunst = Natur – x“ (Holz)', ex:'Hauptmann „Die Weber“, „Bahnwärter Thiel“; Holz/Schlaf „Papa Hamlet“', fx:'Lehrplan: „Abbildung der sozialen Wirklichkeit im Naturalismus“. Vom Realismus durch Verzicht auf Verklärung unterschieden.' },
  { id:'p10', deck:'epochen', term:'Jahrhundertwende / Moderne (Ästhetizismus, Symbolismus)', def:'ca. 1890–1920 · Gegenbewegung zum Naturalismus: Kunst um der Kunst willen (l\'art pour l\'art) · Sprachskepsis (Hofmannsthals „Chandos-Brief“ 1902) · Ich-Dissoziation, Nihilismus (Nietzsche), Décadence · Impressionismus, Symbolismus, Jugendstil', ex:'Hofmannsthal; Rilke „Der Panther“; Schnitzler „Leutnant Gustl“; Stefan George; Th. Mann „Tod in Venedig“', fx:'Lehrplan: „Nihilismus, Sprachskepsis, Ich-Dissoziation … ästhetizistische Tendenzen“.' },
  { id:'p11', deck:'epochen', term:'Expressionismus', def:'ca. 1910–1925 · Ausdruck des inneren Erlebens statt Abbildung · Themen: Großstadt, Krieg, Ich-Zerfall, Weltende, Vater-Sohn-Konflikt · Pathos, Schrei, Farbchiffren, Reihungsstil, Neologismen, „O Mensch“-Pathos', ex:'van Hoddis „Weltende“; Heym „Der Gott der Stadt“; Trakl „Grodek“; Benn „Morgue“; Kafka (Randfigur)', fx:'Merkhilfe: Expression = hinausdrücken (innen → außen); Impression = eindrücken (außen → innen).' },
  { id:'p12', deck:'epochen', term:'Neue Sachlichkeit / Weimarer Republik', def:'ca. 1920–1933 · nüchtern, dokumentarisch, gebrauchsorientiert · Großstadt, Technik, Arbeitslosigkeit · Reportage, Montage · Brechts episches Theater entsteht', ex:'Kästner „Fabian“; Döblin „Berlin Alexanderplatz“; Fallada „Kleiner Mann – was nun?“; Brecht „Dreigroschenoper“', fx:'Lehrplan: „didaktische und parabolische Formen“ – Brecht, Kafka.' },
  { id:'p13', deck:'epochen', term:'Exilliteratur', def:'1933–1945 · Literatur der aus NS-Deutschland vertriebenen Autoren · Auseinandersetzung mit Faschismus, Heimatverlust, Widerstand · oft Parabeln und historische Verkleidung', ex:'Brecht „Leben des Galilei“, „Mutter Courage“; Anna Seghers „Das siebte Kreuz“; Th. Mann; Zuckmayer', fx:'Gegenpol: „Innere Emigration“ (im Land geblieben, unpolitisch geschrieben).' },
  { id:'p14', deck:'epochen', term:'Trümmer- / Nachkriegsliteratur', def:'1945–ca. 1950 · „Kahlschlag“, „Stunde Null“ · schmucklose, knappe Sprache · Heimkehrer, Schuld, Trümmer · Kurzgeschichte als Leitgattung · Gruppe 47', ex:'Borchert „Draußen vor der Tür“, „Das Brot“; Eich „Inventur“; Böll; Celan „Todesfuge“ (Sonderfall)', fx:'Lehrplan: „Aufarbeitung der Vergangenheit“.' },
  { id:'p15', deck:'epochen', term:'Literatur der BRD und DDR (1950–1989)', def:'BRD: Gesellschaftskritik, Vergangenheitsbewältigung, 68er-Politisierung, dann „Neue Subjektivität“ (1970er: Ich, Alltag, Innerlichkeit). DDR: Sozialistischer Realismus, Aufbauliteratur, später kritische Stimmen', ex:'Grass „Die Blechtrommel“; Frisch „Homo faber“; Dürrenmatt „Die Physiker“; Böll; Christa Wolf „Der geteilte Himmel“; Plenzdorf „Die neuen Leiden des jungen W.“', fx:'Lehrplan: „System- und Gesellschaftskritik in beiden deutschen Staaten, Hinwendung zur Subjektivität“.' },
  { id:'p16', deck:'epochen', term:'Gegenwartsliteratur (seit 1989)', def:'seit dem Mauerfall · Rückschau und Standortbestimmung (Wende) · Identität, Pluralität, Migration, Globalisierung, Digitalisierung · Popliteratur, neue Erzähllust, Autofiktion', ex:'Schlink „Der Vorleser“; Herrndorf „Tschick“; Kehlmann „Die Vermessung der Welt“; Juli Zeh; Saša Stanišić; Terézia Mora', fx:'Lehrplan: „Identität, Pluralität, Globalisierung, Migration sowie aktuelle Diskurse“.' },
  { id:'p17', deck:'epochen', term:'Empfindsamkeit', def:'ca. 1740–1780 · Strömung innerhalb der Aufklärung: Gefühl, Seele, Freundschaft, Tränen als Ergänzung zur Vernunft · Brief- und Tagebuchform', ex:'Klopstock; Gellert; Goethes „Werther“ (Briefroman) steht an der Grenze zum Sturm und Drang', fx:'Beweis, dass Aufklärung nicht nur kalte Vernunft war.' },

  /* ───────────── SPRACHE & KOMMUNIKATION ───────────── */
  { id:'k01', deck:'sprache', term:'Organon-Modell (Bühler)', def:'Sprachliches Zeichen hat drei Funktionen: Ausdruck (Beziehung zum Sender), Appell (zum Empfänger), Darstellung (zu Gegenständen/Sachverhalten).', ex:'„Es zieht!“ = Darstellung (offenes Fenster) + Ausdruck (ich friere) + Appell (mach zu)', fx:'Karl Bühler 1934; Organon = Werkzeug. Grundlage für Schulz von Thun.' },
  { id:'k02', deck:'sprache', term:'Vier-Seiten-Modell (Schulz von Thun)', def:'Jede Nachricht hat vier Seiten: Sachinhalt, Selbstoffenbarung, Beziehung, Appell – und der Empfänger hört mit „vier Ohren“.', ex:'„Da vorne ist grün.“ → Sache: Ampel grün; Selbst: ich habe es eilig; Beziehung: du brauchst Hilfe; Appell: fahr los', fx:'Missverständnis = Sender und Empfänger gewichten die Seiten unterschiedlich.' },
  { id:'k03', deck:'sprache', term:'Fünf Axiome (Watzlawick)', def:'1. Man kann nicht nicht kommunizieren. 2. Jede Kommunikation hat Inhalts- und Beziehungsaspekt. 3. Interpunktion der Ereignisfolge. 4. Digital (Worte) und analog (Körper). 5. Symmetrisch oder komplementär.', ex:'Schweigen im Zug ist auch eine Botschaft (Axiom 1); „Du hast angefangen!“ (Axiom 3)', fx:'Watzlawick, „Menschliche Kommunikation“ 1969. Für Analyse gestörter Kommunikation in Dramen und Erzählungen.' },
  { id:'k04', deck:'sprache', term:'Sender-Empfänger-Modell (Shannon/Weaver)', def:'Technisches Modell: Sender kodiert eine Nachricht, sendet sie über einen Kanal, Empfänger dekodiert; Störungen („Rauschen“) verfälschen.', ex:'Telefonat mit schlechter Verbindung; Sender und Empfänger haben unterschiedliche „Codes“', fx:'Einfachstes Modell; blendet Beziehung und Kontext aus – Kritikpunkt.' },
  { id:'k05', deck:'sprache', term:'Denotation / Konnotation', def:'Denotation: sachliche Grundbedeutung eines Wortes. Konnotation: mitschwingende Neben- und Gefühlsbedeutung.', ex:'„Köter“ und „Hund“ denotieren dasselbe Tier, konnotieren aber verschieden', fx:'Lehrplan D12 4.2 nennt es ausdrücklich. Wortwahl-Analyse in Sachtexten läuft darüber.' },
  { id:'k06', deck:'sprache', term:'Sprachvarietäten', def:'Ausprägungen einer Sprache: Standardsprache, Dialekt (regional), Soziolekt (Gruppe: Jugendsprache, Fachsprache), Idiolekt (Einzelperson), Register (Situation).', ex:'Bairisch (Dialekt), Jugendsprache (Soziolekt), Juristendeutsch (Fachsprache)', fx:'Frage in der Analyse: Welche Varietät, mit welcher Wirkung (Nähe, Distanz, Abgrenzung)?' },
  { id:'k07', deck:'sprache', term:'Sprachwandel', def:'Sprache verändert sich ständig: Wortschatz (Anglizismen, Neologismen), Grammatik (Genitivschwund), Aussprache, Bedeutung. Ursachen: Ökonomie, Prestige, Medien, Kontakt.', ex:'„weil“ mit Hauptsatzstellung; „Sinn machen“; gendergerechte Sprache', fx:'Diskussion: Sprachverfall oder natürlicher Wandel? Prüfungsklassiker für materialgestütztes Argumentieren.' },
  { id:'k08', deck:'sprache', term:'Sapir-Whorf-Hypothese', def:'Sprache bestimmt (starke Form) bzw. beeinflusst (schwache Form) das Denken und die Wahrnehmung der Wirklichkeit – „linguistische Relativität“.', ex:'Sprachen mit vielen Schneewörtern, Zeitvorstellungen in Grammatiken', fx:'Starke Form gilt als widerlegt, schwache Form als belegt. Gehört zu „Sprache, Wirklichkeit und Denken“ im Lehrplan.' },
  { id:'k09', deck:'sprache', term:'Humboldt: Sprache als Weltansicht', def:'Wilhelm von Humboldt: Jede Sprache enthält eine eigene „Weltansicht“; Sprache ist das „bildende Organ des Gedankens“ – Denken geschieht in und durch Sprache.', ex:'Verschiedene Sprachen gliedern die Welt verschieden', fx:'Vorläufer von Sapir-Whorf; sprachphilosophische Position für D12 4.1.' },
  { id:'k10', deck:'sprache', term:'Wittgenstein', def:'„Die Grenzen meiner Sprache bedeuten die Grenzen meiner Welt.“ (Tractatus) – Was nicht sagbar ist, ist nicht denkbar. Später: Bedeutung = Gebrauch (Sprachspiele).', ex:'Ohne ein Wort für ein Gefühl bleibt es unscharf', fx:'Wird gern mit Sprachskepsis (Hofmannsthal) und Sapir-Whorf verknüpft.' },
  { id:'k11', deck:'sprache', term:'Sprachliches Zeichen (Saussure)', def:'Zeichen = Signifikant (Lautbild, „Bezeichnendes“) + Signifikat (Vorstellung, „Bezeichnetes“). Die Verbindung ist arbiträr (willkürlich, nur durch Konvention).', ex:'„Baum“, „tree“, „arbre“ – verschiedene Lautbilder, dieselbe Vorstellung', fx:'Ferdinand de Saussure, Begründer der modernen Linguistik.' },
  { id:'k12', deck:'sprache', term:'Sprachskepsis / Sprachkrise', def:'Zweifel, ob Sprache Wirklichkeit und Inneres überhaupt ausdrücken kann; die Wörter „zerfallen im Munde wie modrige Pilze“.', ex:'Hofmannsthal, „Ein Brief“ (Chandos-Brief, 1902); Rilke; Kafka', fx:'Zentral für die Moderne um 1900; Lehrplan nennt „Sprachskepsis“ ausdrücklich.' },
  { id:'k13', deck:'sprache', term:'Verbal / paraverbal / nonverbal', def:'Verbal: die Worte. Paraverbal: Stimme (Lautstärke, Tempo, Tonfall, Pausen). Nonverbal: Körper (Mimik, Gestik, Haltung, Blick, Distanz).', ex:'„Ja, super.“ – Bedeutung hängt am Tonfall (paraverbal) und Augenrollen (nonverbal)', fx:'Lehrplan D12 4.1: Zusammenspiel analysieren, Machtsignale erkennen.' },
  { id:'k14', deck:'sprache', term:'Framing', def:'Deutungsrahmen: Durch Wortwahl wird ein Sachverhalt in einen bestimmten Bewertungsrahmen gestellt.', ex:'„Steuerlast“ vs. „Steuerbeitrag“; „Flüchtlingswelle“ vs. „Schutzsuchende“', fx:'Persuasive Strategie; Lehrplan D12 2.3 nennt Framing, Narrative, Agenda-Setting.' },
  { id:'k15', deck:'sprache', term:'Agenda-Setting', def:'Medien bestimmen nicht, WAS wir denken, aber WORÜBER wir nachdenken – durch Auswahl und Gewichtung der Themen.', ex:'Ein Thema, das täglich auf Seite 1 steht, gilt als wichtig', fx:'McCombs/Shaw 1972. Mit Framing und Narrativ das Dreieck der Medienkritik.' },
  { id:'k16', deck:'sprache', term:'Narrativ', def:'Sinnstiftende Erzählung, die Ereignisse in ein Deutungsmuster einordnet und Identität stiftet.', ex:'„Vom Tellerwäscher zum Millionär“; „Wirtschaftswunder“', fx:'Fragt in Sachtexten: Welche Geschichte wird über die Fakten gelegt?' },
  { id:'k17', deck:'sprache', term:'Persuasive Strategien', def:'Mittel, um Zustimmung zu erzeugen: Schlagwörter, Euphemismen, Suggestivfragen, Wir-Gefühl, Feindbilder, Autoritätsverweise, Emotionalisierung, Wiederholung.', ex:'Wahlkampfreden, Werbung, Social-Media-Posts', fx:'Lehrplan 4.1: „persuasive und manipulative Strategien … kritisch bewerten“.' },
  { id:'k18', deck:'sprache', term:'Kohärenz / Kohäsion', def:'Kohärenz: inhaltlich-logischer Zusammenhang eines Textes. Kohäsion: sprachliche Verknüpfungsmittel (Konnektoren, Pronomen, Wiederaufnahme).', ex:'„deshalb“, „allerdings“, „dieser“ (Kohäsion) – roter Faden (Kohärenz)', fx:'Lehrplan 3.1 verlangt beides für eigene Texte. Ein Text kann kohäsiv, aber inkohärent sein.' },
  { id:'k19', deck:'sprache', term:'Mehrsprachigkeit / Code-Switching', def:'Wechsel zwischen Sprachen oder Varietäten innerhalb eines Gesprächs, je nach Situation, Partner, Thema.', ex:'Türkisch zu Hause, Deutsch in der Schule, Englisch im Chat – manchmal im selben Satz', fx:'Lehrplan 4.1: Mehrsprachigkeit als Ressource, nicht Defizit.' },
  { id:'k20', deck:'sprache', term:'Sprachebenen (Register)', def:'Stilhöhe je nach Situation: gehoben – standardsprachlich – umgangssprachlich – salopp/vulgär.', ex:'„speisen“ – „essen“ – „futtern“ – „fressen“', fx:'Registerbruch als Stilmittel (Komik, Ironie) erkennen.' },
  { id:'k21', deck:'sprache', term:'Interpunktion (Watzlawick, Axiom 3)', def:'Kommunikationspartner gliedern denselben Ablauf unterschiedlich in Ursache und Wirkung – jeder sieht sich als Reagierenden.', ex:'Er zieht sich zurück, weil sie nörgelt – sie nörgelt, weil er sich zurückzieht', fx:'Erklärt Teufelskreise in Paarkonflikten; anwendbar auf Dramendialoge.' },
  { id:'k22', deck:'sprache', term:'Symmetrisch / komplementär (Watzlawick, Axiom 5)', def:'Symmetrisch: Partner auf Augenhöhe, streben nach Gleichheit. Komplementär: ungleiche Rollen ergänzen sich (oben/unten).', ex:'Lehrer–Schüler (komplementär), zwei Freunde (symmetrisch)', fx:'Störung: symmetrische Eskalation (Wettstreit) oder starre Komplementarität.' },

  /* ───────────── ARGUMENTATION & AUFSATZ ───────────── */
  { id:'a01', deck:'argu', term:'These – Argument – Beleg', def:'Aufbau eines Arguments: These (Behauptung) → Argument (Begründung, warum) → Beleg/Beispiel (Stütze) → ggf. Schlussfolgerung.', ex:'Handys stören den Unterricht (These), weil sie Aufmerksamkeit binden (Argument); Studie X zeigt … (Beleg)', fx:'Drei-Schritt immer prüfen: Fehlt der Beleg, ist es nur eine Behauptung.' },
  { id:'a02', deck:'argu', term:'Faktenargument', def:'Stützt sich auf überprüfbare Tatsachen, Zahlen, Daten.', ex:'„Laut Statistischem Bundesamt sank die Zahl um 12 %.“', fx:'Stark, wenn die Quelle seriös ist; prüfen, ob die Zahl zum Punkt passt.' },
  { id:'a03', deck:'argu', term:'Autoritätsargument', def:'Beruft sich auf eine anerkannte Instanz (Experte, Institution, Studie).', ex:'„Wie die WHO betont, …“', fx:'Schwach, wenn die Autorität fachfremd ist oder nur ihr Name zählt.' },
  { id:'a04', deck:'argu', term:'Normatives Argument', def:'Beruft sich auf allgemein anerkannte Werte und Normen (Gerechtigkeit, Freiheit, Menschenwürde).', ex:'„Jeder Mensch hat das Recht auf Bildung, deshalb …“', fx:'Wirkt stark, setzt aber voraus, dass der Adressat die Norm teilt.' },
  { id:'a05', deck:'argu', term:'Analogisierendes Argument', def:'Überträgt einen Sachverhalt auf einen vergleichbaren anderen Bereich.', ex:'„So wie man Autofahren lernen muss, muss man auch Medienkompetenz lernen.“', fx:'Anschaulich, aber angreifbar: Hinkt der Vergleich?' },
  { id:'a06', deck:'argu', term:'Indirektes Argument', def:'Entkräftet die Gegenposition und stützt so die eigene.', ex:'„Wer sagt, Lesen sei überflüssig, übersieht, dass …“', fx:'Zeigt Auseinandersetzung mit Gegenargumenten – in der Erörterung Pflicht.' },
  { id:'a07', deck:'argu', term:'Plausibilitätsargument', def:'Beruft sich auf allgemeine Lebenserfahrung und Einleuchtendes („jeder weiß“).', ex:'„Wer müde ist, lernt schlechter – das kennt jeder.“', fx:'Schwächstes Argument: nicht überprüfbar, aber wirksam beim Publikum.' },
  { id:'a08', deck:'argu', term:'Lineare Erörterung', def:'Nur eine Position wird entfaltet, Argumente steigernd geordnet (schwächstes zuerst, stärkstes zuletzt).', ex:'„Warum sollte Regensburg mehr Radwege bauen?“', fx:'Lehrplan 3.2: „linear“. Fragestellung ohne echtes Pro/Contra.' },
  { id:'a09', deck:'argu', term:'Antithetische (dialektische) Erörterung', def:'Pro und Contra werden getrennt entfaltet, dann Synthese/eigene Position. Aufbau: Sanduhr (starke Gegenargumente zuerst, dann eigene steigernd) oder Blockform.', ex:'„Sollte das Abitur bundesweit einheitlich sein?“', fx:'Lehrplan 3.2: „antithetisch“. Nicht mit Ping-Pong-Aufzählung verwechseln – Blöcke bilden.' },
  { id:'a10', deck:'argu', term:'Aspektorientierte Erörterung', def:'Ein Thema wird nach Gesichtspunkten (z. B. ökonomisch, ökologisch, sozial) gegliedert, nicht nach Pro/Contra.', ex:'„Folgen der Digitalisierung für die Schule“ – Aspekte: Lernen, Soziales, Kosten', fx:'Lehrplan 3.2: „aspektorientiert“. Typisch für materialgestütztes Informieren/Erörtern.' },
  { id:'a11', deck:'argu', term:'Essay', def:'Subjektiver, gedanklich freier Text zu einer Frage; assoziativ, pointiert, mit persönlicher Haltung, ohne starres Gliederungsschema; sprachlich anspruchsvoll.', ex:'Montaigne (Erfinder), Enzensberger, Sibylle Berg', fx:'Lehrplan: „essayistisch“, „assoziativ“. Kein Aufsatz mit „Einleitung–Hauptteil–Schluss“-Etiketten.' },
  { id:'a12', deck:'argu', term:'Kommentar', def:'Meinungsbetonte journalistische Textsorte: nimmt zu einem aktuellen Thema Stellung, argumentiert, wertet, oft pointiert.', ex:'Kommentarspalte in SZ, FAZ, Zeit', fx:'Lehrplan: „kommentierend“. Unterschied zur Nachricht: Wertung erlaubt und erwünscht.' },
  { id:'a13', deck:'argu', term:'Glosse', def:'Kurze, polemisch-witzige journalistische Textsorte, die einen Sachverhalt ironisch zuspitzt.', ex:'„Streiflicht“ (SZ)', fx:'Ironie, Übertreibung, Wortspiel als Hauptmittel.' },
  { id:'a14', deck:'argu', term:'Materialgestütztes Schreiben', def:'Verfassen eines informierenden oder argumentierenden Textes auf Grundlage mehrerer vorgegebener Materialien (Texte, Grafiken, Statistiken), die ausgewertet und eingebunden werden.', ex:'„Verfassen Sie auf Basis der Materialien M1–M4 einen Kommentar für die Schülerzeitung.“', fx:'Lehrplan 3.2. Fallen: Material nur nacherzählen statt nutzen; Adressat und Textsorte ignorieren.' },
  { id:'a15', deck:'argu', term:'Deutungshypothese', def:'Vorläufige These über die Gesamtaussage eines literarischen Textes, die die Analyse leitet und am Ende bestätigt/modifiziert wird.', ex:'„Das Gedicht zeigt, dass Naturerfahrung Ersatz für verlorene Religion wird.“', fx:'Lehrplan 3.2: „eine Deutungshypothese formulieren und begründen“. Kommt nach der Inhaltsangabe, vor der Analyse.' },
  { id:'a16', deck:'argu', term:'Aufbau der Texterschließung (literarisch)', def:'1. Einleitung (Autor, Titel, Gattung, Entstehungszeit, Thema) 2. Inhaltsangabe 3. Deutungshypothese 4. Analyse: Aufbau, Sprache, Form, gattungsspezifische Mittel – immer mit Funktion 5. Deutung im Kontext (Epoche) 6. Schluss/Fazit', ex:'Merkhilfe für die Einleitung: TATTE (Titel, Autor, Textsorte, Thema, Entstehungszeit)', fx:'Lehrplan 3.2: „informieren, Deutungshypothese, argumentativ erläutern, Kontextwissen“.' },
  { id:'a17', deck:'argu', term:'Aufbau der Sachtextanalyse', def:'1. Einleitung (Autor, Titel, Textsorte, Erscheinungsort/-datum, Thema) 2. Inhalt/Kernthese 3. Argumentationsstruktur (Thesen, Argumenttypen, Aufbau) 4. Sprache und Stil (Wortwahl, Satzbau, rhetorische Mittel) mit Funktion 5. Intention und Adressat 6. ggf. Stellungnahme', ex:'„Der Autor will überzeugen, erkennbar an rhetorischen Fragen und Wir-Ansprache.“', fx:'Lehrplan 3.2: „Inhalt, Struktur, argumentative Gestaltung, Sprache und Stil, Adressatenbezug, Intention“.' },
  { id:'a18', deck:'argu', term:'Zitierregeln', def:'Direktes Zitat in Anführungszeichen mit Zeilen-/Versangabe (Z. 12 f. / V. 3–5); Auslassungen mit [...]; grammatische Anpassungen in eckigen Klammern; indirektes Zitat im Konjunktiv (vgl. Z. 8).', ex:'Der Erzähler nennt ihn einen „Mann ohne Eigenschaften“ (Z. 4).', fx:'Jede Behauptung über den Text braucht einen Beleg. „f.“ = folgende Zeile, „ff.“ = mehrere.' },
  { id:'a19', deck:'argu', term:'Fehlschlüsse', def:'Logische Fehler in Argumentationen: Verallgemeinerung (ein Fall → alle), Zirkelschluss (These begründet sich selbst), Strohmann (verzerrte Gegenposition), falsche Kausalität (post hoc), ad hominem (Angriff auf die Person), falsches Dilemma (nur zwei Optionen).', ex:'„Alle Jugendlichen sind handysüchtig, mein Bruder ist es auch.“ (Verallgemeinerung)', fx:'Lehrplan 3.2: „Verallgemeinerungen, Fehlschlüsse und Pauschalurteile vermeiden“.' },
  { id:'a20', deck:'argu', term:'Einräumung (Konzession)', def:'Ein Gegenargument wird anerkannt, dann aber entkräftet oder relativiert: „Zwar …, aber …“', ex:'„Zwar kostet ein Ausbau des ÖPNV Geld, aber die Folgekosten des Autoverkehrs sind höher.“', fx:'Lehrplan 3.2: „auf Gegenargumente eingehen, Einräumungen vornehmen“. Zeigt Abwägung.' },
  { id:'a21', deck:'argu', term:'Intention / Adressat', def:'Intention: Was will der Text (informieren, überzeugen, appellieren, unterhalten, kritisieren)? Adressat: An wen richtet er sich (erkennbar an Anrede, Register, Vorwissen)?', ex:'Werbetext: Intention = kaufen; Adressat = junge Erwachsene (Duzen, Jugendsprache)', fx:'Beides gehört in jede Sachtextanalyse – und begründet die Wahl der sprachlichen Mittel.' },
  { id:'a22', deck:'argu', term:'Rede (Textsorte)', def:'Mündlich vorgetragener, appellativer Text; Mittel: Anrede, rhetorische Fragen, Wir-Gefühl, Wiederholung, Klimax, Pathos; Aufbau meist Einleitung – Argumentation – Appell.', ex:'Politische Reden, Festreden, historische Reden (z. B. Weizsäcker 1985)', fx:'Redeanalyse: Anlass, Redner, Publikum, Ziel – dann Mittel und Wirkung.' },
  { id:'a23', deck:'argu', term:'Textsorten-Merkmale (Sachtexte)', def:'Nachricht/Bericht: informierend, sachlich. Reportage: informierend, anschaulich, subjektiv gefärbt. Kommentar/Leitartikel: meinungsbildend. Glosse: polemisch-witzig. Essay: reflektierend. Rezension: bewertend.', ex:'„Reportage aus dem Flüchtlingslager“ vs. „Kommentar zur Asylpolitik“', fx:'Textsorte immer in der Einleitung benennen – sie erklärt Sprache und Intention.' },
  { id:'a24', deck:'argu', term:'Sanduhr-Prinzip', def:'Aufbau der antithetischen Erörterung: Gegenposition mit stärkstem Argument beginnen und absteigend ordnen, dann eigene Position aufsteigend bis zum stärksten Argument – Schluss ist die eigene Meinung.', ex:'Contra: stark → schwach | Pro: schwach → stark', fx:'Der letzte Eindruck bleibt – deshalb das eigene stärkste Argument ans Ende.' },
];
